spec.query:
from(bucket: "${bucket}")
  |> range(start: -365d)
  |> filter(fn: (r) =>
    r._measurement == "fl_experiment_summary" or
    r._measurement == "fl_run_summary"
  )
  |> filter(fn: (r) => r.run_id == "${run_id}")
  |> filter(fn: (r) => r._field == "duration_s")
  |> map(fn: (r) => ({
    r with
    _value: float(v: r._value)
  }))
  |> last()
  |> map(fn: (r) => ({
    "Duration [s]": r._value,
    "Model": if exists r.model then r.model else "unknown",
    "Split": if exists r.split then r.split else
      if r.run_id =~ /weighted_iid/ then "weighted_iid"
      else if r.run_id =~ /iid/ then "iid"
      else "unknown",
    "Strategy": if exists r.strategy then r.strategy else "unknown"
  }))
